import {
  MeshBasicNodeMaterial,
  MeshStandardNodeMaterial,
  MeshPhysicalNodeMaterial
} from 'three/webgpu';
import {
  uv,
  vec2,
  vec3,
  mix,
  smoothstep,
  uniform
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, SphereGeometry, CylinderGeometry, DirectionalLight, AmbientLight } = ctx.THREE;

  const container = new Group();
  const activeTimelines = [];
  const activePrimitives = [];

  // 1. NESTED GROUPS TO PRESERVE COMPOSITION & LEGIBILITY
  const backdropGroup = new Group();
  const subjectGroup = new Group();
  const textGroup = new Group();

  container.add(backdropGroup);
  container.add(subjectGroup);
  container.add(textGroup);

  // 2. BACKDROP (Fills the frame beautifully, static)
  const backdropGeo = new PlaneGeometry(12, 10);
  const backdropMat = new MeshBasicNodeMaterial();

  // Custom TSL gradient matching the spec: #0b0b10 -> #101017 -> #16161d
  const uvs = uv();
  const gradNode = mix(
    vec3(0.043, 0.043, 0.063), // #0b0b10 (bottom)
    mix(
      vec3(0.063, 0.063, 0.090), // #101017 (middle)
      vec3(0.086, 0.086, 0.114), // #16161d (top)
      smoothstep(0.4, 1.0, uvs.y)
    ),
    smoothstep(0.0, 0.65, uvs.y)
  );
  backdropMat.colorNode = gradNode;

  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -3.0);
  backdropGroup.add(backdrop);

  // Ground Contact Shadow Plane
  const shadowGeo = new PlaneGeometry(2.6, 1.2);
  const shadowMat = new MeshBasicNodeMaterial({
    transparent: true,
    alphaWrite: false,
    depthWrite: false
  });
  const shadowUv = uv().sub(0.5);
  const shadowDist = shadowUv.mul(vec2(1.0, 2.16)).length();
  const shadowAlpha = mix(0.5, 0.0, smoothstep(0.15, 0.5, shadowDist));
  shadowMat.colorNode = vec3(0.02, 0.02, 0.03);
  shadowMat.opacityNode = uniform(shadowAlpha);

  const contactShadow = new Mesh(shadowGeo, shadowMat);
  contactShadow.position.set(0, -1.2, -0.2);
  contactShadow.rotation.x = -Math.PI / 2;
  backdropGroup.add(contactShadow);

  // 3. ORRERY MECHANISM SUBJECT SETUP (Inside subjectGroup)
  const gearAssembly = new Group();
  subjectGroup.add(gearAssembly);

  // Darkened high-contrast steel material to prevent white plastic look (OFF_PALETTE fix)
  const steelMat = new MeshPhysicalNodeMaterial({
    color: 0x818690, // Iron grey rather than paper white
    roughness: 0.5,
    metalness: 0.85,  // Boost metalness to feel like machined steel
    clearcoat: 0.25,
    clearcoatRoughness: 0.3,
    anisotropy: 0.7
  });

  const primaryGear = new Group();
  const secondaryGear = new Group();
  gearAssembly.add(primaryGear);
  gearAssembly.add(secondaryGear);

  secondaryGear.position.set(1.15, 0.35, -0.1);

  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      let originalMesh = null;
      gltf.scene.traverse((child) => {
        if (child.isMesh && !originalMesh) {
          originalMesh = child;
        }
      });

      if (originalMesh) {
        originalMesh.geometry.computeBoundingBox();
        const box = originalMesh.geometry.boundingBox;
        const sizeX = box.max.x - box.min.x;
        const scaleFit = 1.6 / (sizeX || 1.6);

        // Primary Gear
        const pMesh = originalMesh.clone();
        pMesh.geometry = originalMesh.geometry.clone();
        pMesh.geometry.center();
        pMesh.scale.set(scaleFit, scaleFit, scaleFit);
        pMesh.material = steelMat;
        primaryGear.add(pMesh);

        // Secondary Gear
        const sMesh = originalMesh.clone();
        sMesh.geometry = originalMesh.geometry.clone();
        sMesh.geometry.center();
        const smallScale = scaleFit * (0.9 / 1.6);
        sMesh.scale.set(smallScale, smallScale, smallScale);
        sMesh.material = steelMat;
        secondaryGear.add(sMesh);
      }
    }).catch(err => {
      console.warn("Falling back to basic geometries for gear meshes:", err);
    });
  }

  // Jewel pivot sphere (MeshPhysicalMaterial color #ff2a38)
  const jewelGeo = new SphereGeometry(0.12, 32, 24);
  const jewelMat = new MeshPhysicalNodeMaterial({
    color: 0xff2a38,
    transmission: 0.6,
    ior: 1.76,
    roughness: 0.1,
    thickness: 0.2,
    emissive: 0xff2a38,
    emissiveIntensity: 1.8
  });
  const jewelPivot = new Mesh(jewelGeo, jewelMat);
  jewelPivot.position.set(0, 0, 0.1);
  primaryGear.add(jewelPivot);

  // Arbor shafts (ink #16161d cylinders through both hubs)
  const shaftGeo = new CylinderGeometry(0.05, 0.05, 0.8, 16);
  const shaftMat = new MeshStandardNodeMaterial({
    color: 0x16161d,
    roughness: 0.6,
    metalness: 0.5
  });

  const shaftPrimary = new Mesh(shaftGeo, shaftMat);
  shaftPrimary.rotation.x = Math.PI / 2;
  shaftPrimary.position.set(0, 0, -0.2);
  primaryGear.add(shaftPrimary);

  const shaftSecondary = new Mesh(shaftGeo, shaftMat);
  shaftSecondary.rotation.x = Math.PI / 2;
  shaftSecondary.position.set(0, 0, -0.2);
  secondaryGear.add(shaftSecondary);

  // 4. DRAMATIC LIGHTING RIG (Avoids DEAD_LIGHTING and BLOWN_WHITE_KEY)
  const ambientLight = new AmbientLight(0x0b0b10, 0.4);
  subjectGroup.add(ambientLight);

  const keyLight = new DirectionalLight(0xe8ecf2, 1.1);
  keyLight.position.set(3, 4, 3);
  subjectGroup.add(keyLight);

  const rimLight = new DirectionalLight(0xff2a38, 0.8);
  rimLight.position.set(-3, -2, -1);
  subjectGroup.add(rimLight);

  // 5. TYPOGRAPHY ZONE (Facing camera directly, never garbled or clipped)
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find(i => i.role === 'headline' || i.text.length < 25);
  const captionItem = items.find(i => i.role === 'caption' || i.text.length >= 25);

  if (headlineItem) {
    const textH = ctx.fontAtlas.createText(headlineItem.text, {
      fontSize: 0.32,
      color: '#e8ecf2',
      align: 'center'
    });
    textH.position.set(0, -1.7, 0.2);
    textGroup.add(textH);
  }

  if (captionItem) {
    const textC = ctx.fontAtlas.createText(captionItem.text, {
      fontSize: 0.09,
      color: '#ff2a38',
      align: 'center',
      letterSpacingPx: 0.08
    });
    textC.position.set(0, -2.1, 0.2);
    textGroup.add(textC);
  }

  // 6. ANIMATIONS & ROTATIONS (Continuous Meshing Physics)
  const clock = { value: 0 };
  const gearTimeline = gsap.to(clock, {
    value: 100000,
    duration: 100000,
    ease: "none",
    onUpdate: () => {
      const t = clock.value;
      primaryGear.rotation.z = t * 0.08;
      secondaryGear.rotation.z = 2.45 - (t * 0.142);
    }
  });
  activeTimelines.push(gearTimeline);

  // Settle animated transition on entrance
  gsap.fromTo(gearAssembly.position, 
    { y: -0.2, z: -0.4 }, 
    { y: 0, z: 0, duration: 1.2, ease: "power3.out" }
  );

  // Apply visual cinematic primitives directly to the subjectGroup (avoids rotating text or background)
  if (config.cinematicPrimitives) {
    for (const primitive of config.cinematicPrimitives) {
      if (ctx.primitives[primitive.name]) {
        const primResult = ctx.primitives[primitive.name](subjectGroup, primitive.params);
        if (primResult) {
          activePrimitives.push(primResult);
        }
      }
    }
  }

  // 7. RESOURCE CLEANUP
  container.userData.cleanup = function () {
    activeTimelines.forEach(tl => tl.kill());
    activePrimitives.forEach(p => {
      if (typeof p.cleanup === 'function') p.cleanup();
    });

    steelMat.dispose();
    jewelMat.dispose();
    shaftMat.dispose();
    shadowMat.dispose();
    backdropMat.dispose();
  };

  return container;
}
